import{_ as t,o as n,c as a,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy testing and evaluation","description":"This is the verification plan for the current game design, not a report of passed tests.\\nCurrent authorization is documentation and necessary preparation only; game developmen","frontmatter":{"title":"Chainy testing and evaluation","description":"This is the verification plan for the current game design, not a report of passed tests.\\nCurrent authorization is documentation and necessary preparation only; game developmen","source":"docs/qa-evaluation.md","category":"Research & evaluation","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/qa-evaluation.md","filePath":"content/docs/qa-evaluation.md"}'),i={name:"content/docs/qa-evaluation.md"};function s(o,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-testing-and-evaluation">Chainy testing and evaluation<a class="header-anchor" href="#chainy-testing-and-evaluation" aria-label="Link to this section">​</a></h1><p>This is the verification plan for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current game design</a>, not a report of passed tests. <strong>Current authorization is documentation and necessary preparation only; game development and runtime verification require final owner approval.</strong> Use <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#12-design-acceptance-cases">LC-G01–19</a> for detailed gameplay acceptance and the <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">baseline</a> for dated implementation evidence. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/qa-evaluation.html">previous plan</a> preserves earlier requirements.</p><h2 id="review-the-design-and-content-now">Review the design and content now<a class="header-anchor" href="#review-the-design-and-content-now" aria-label="Link to this section">​</a></h2><p>Check that the route has 13 distinct lessons per world, 39 total, with three distinct minigames per world and 30 ordinary collectibles. Each term needs a source, explanation, example, and one four-choice review question with a correct answer and explanatory feedback. Check that the nine activities teach their stated concepts through their actual player rules. AI activities must describe themselves as offline teaching simulations.</p><p>The required quiz contains all 13 questions for that world, one per lesson. Incorrect answers receive feedback and must be retried until all 13 are correct. Keep first-response scores separate from corrected completion; correction does not turn earlier mistakes into a perfect first-response score. Writing and reviewing these documents does not validate learning outcomes or establish a working build.</p><h2 id="planned-runtime-checks">Planned runtime checks<a class="header-anchor" href="#planned-runtime-checks" aria-label="Link to this section">​</a></h2><p>Run these only after development is authorized, against a named revision and build. Use synthetic profiles and the GDD&#39;s exact lesson/activity IDs.</p><table><thead><tr><th>Area</th><th>Setup and action</th><th>Expected result</th></tr></thead><tbody><tr><td>World access and tutorial</td><td>Start a new profile; try all world cards; visit the first island</td><td>Only Web3 opens initially; orientation introduces controls and finishes before lessons can advance</td></tr><tr><td>Ordered collection</td><td>Inspect an ordinary current object, then a later object; record and revisit the current object</td><td>Only the current lesson records; its explanation remains available; repeat interaction cannot duplicate the entry</td></tr><tr><td>Nine minigames</td><td>For each activity, try its item/NPC/facility steps out of order, then in order; complete its stated rule</td><td>Only the valid sequence opens the separate scene; the correct lesson records after successful saving</td></tr><tr><td>Retry, exit and return</td><td>Make a wrong action, retry, exit unfinished, then return and succeed</td><td>Retry stays in the activity; exit grants no entry; saved prerequisites remain; success returns to the originating island</td></tr><tr><td>Required review</td><td>Collect 13 entries; answer some review items incorrectly; correct every item</td><td>Collection alone does not unlock the next world; all 13 questions must be resolved and review completion saved</td></tr><tr><td>Quiz abandonment and replay</td><td>Leave an unfinished quiz and revisit a completed quiz</td><td>Attempt handling follows the GDD; incomplete work is not a completed score; replay cannot revoke an existing unlock</td></tr><tr><td>Atomic progress and recovery</td><td>Repeat completion taps; interrupt a save; retry and relaunch</td><td>Entry, next objective and unlock state agree; failed saves show recovery without false completion or silent reset</td></tr><tr><td>Profile isolation</td><td>Alternate two synthetic profiles across islands and relaunch</td><td>Each profile restores only its own entries, quiz attempts and world access</td></tr><tr><td>Touch and interruption</td><td>Use dialogue, Quest, Encyclopedia and Pause; background and resume Android</td><td>Only the active layer accepts input; movement does not remain held; feedback works without sound or color alone</td></tr><tr><td>Offline journey</td><td>Complete Web3, Blockchain and AI in airplane mode on the reference phone</td><td>All 39 entries, nine activities and three required quizzes work without a network dependency</td></tr></tbody></table><p>Record each case&#39;s requirement, setup, steps, expected result, actual result, pass/fail/not-run state, revision/build, device, date, tester and evidence location. For a defect, include reproducible steps, observed impact, affected requirement and retest result. An unresolved result remains visible; a completed document or board card is not a runtime pass.</p><p>The required reference check uses Android 10/API 29, 4 GB physical RAM, 128 GB total storage and a reported 2.3 GHz octa-core CPU. API 25 remains the minimum install setting, not proof that gameplay works on every such device. Use <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware validation</a> for device details and measurements. Desktop checks and higher-spec phones do not replace the reference-phone result.</p><h2 id="learner-sessions-and-evidence">Learner sessions and evidence<a class="header-anchor" href="#learner-sessions-and-evidence" aria-label="Link to this section">​</a></h2><p>Sean prepares the written protocol; Sherwin confirms arrangements and the appropriate school/site approvals. Before involving learners, confirm participant criteria, consent and guardian permission where needed, accessibility, assistance rules, instrument, analysis, custodian, access and retention with the responsible adviser/organizer. Keep participant identities and raw records in approved restricted storage, outside repositories and public issues.</p><p>Use neutral instructions, disclose the build&#39;s tested features and limitations, and record assistance, interruptions and missing responses. Report observations, participant feedback, measures and interpretation separately. First responses within the taught game are distinct from an adviser-approved independent learning assessment. Collected entries, corrected quizzes and enjoyment do not establish mastery or learning gains; a pre/post difference alone does not establish causation. Teacher services and export features are outside the game scope; evidence arrangements must not assume those features exist.</p><h2 id="readiness-and-remaining-evidence">Readiness and remaining evidence<a class="header-anchor" href="#readiness-and-remaining-evidence" aria-label="Link to this section">​</a></h2><p>The actual outcome of the November 10 Cryptita Plays session, the school&#39;s exact “ISO 2010” instrument, its completion calculation and acceptance of community evidence remain unverified. Use the <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">manuscript evidence map</a> to track those questions. <strong>Pre-final remains November 21, 2026.</strong> Rebaseline unfinished board work after documentation review, preserving integration, device QA, manuscript and rehearsal time. This plan does not establish that the complete design is feasible by that date.</p></div>',1)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
